{ # Query address with valid fields and an error field (invalid pagination).
  # The response should have both data (for successful fields) AND errors (for failed field)
  address(address: "@{A}") {
    # Valid field
    address
    # Error field - first and last together is invalid
    objects(first: 1, last: 1) {
      nodes {
        address
      }
    }
  }
}

{
  # Test partial error at query root level
  # One query succeeds with all fields, another has partial error
  validAddress: address(address: "@{A}") {
    address
  }

  partialErrorAddress: address(address: "@{A}") {
    address
    # Error field - first and last together is invalid
    balances(first: 1, last: 1) {
      nodes {
        coinType { repr }
      }
    }
  }
}

{ # Only the outermost Bag is still accessible, the rest are wrapped.
  multiGetObjects(keys: [
    { address: "@{obj_1_0}" },
    { address: "@{obj_2_0}" },
    { address: "@{obj_3_0}" },
    { address: "@{obj_4_0}" },
  ]) {
    version
    asMoveObject {
      contents { json }
    }
  }
}

{ # At the previous checkpoint, they were all accessible
  checkpoint(sequenceNumber: 1) {
    query {
      multiGetObjects(keys: [
        { address: "@{obj_1_0}" },
        { address: "@{obj_2_0}" },
        { address: "@{obj_3_0}" },
        { address: "@{obj_4_0}" },
      ]) {
        version
        asMoveObject {
          contents { json }
        }
      }
    }
  }
}

{ # The outermost Bag can be accessed with `address` or `object`
  address(address: "@{obj_1_0}") {
    dynamicField(name: { type: "u64", bcs: "@{cursor_0}" }) {
      value { ... on MoveValue { json } }
    }
  }

  object(address: "@{obj_1_0}") {
    asMoveObject {
      dynamicField(name: { type: "u64", bcs: "@{cursor_0}" }) {
        value { ... on MoveValue { json } }
      }
    }
  }
}

{ # The middle Bag is not accessible, so we need to use `address` to root
  # further dynamic field queries.
  address(address: "@{obj_2_0}", rootVersion: 7) {
    df2: dynamicField(name: { type: "u64", bcs: "@{cursor_0}" }) { ...DF }
    df3: dynamicField(name: { type: "u64", bcs: "@{cursor_1}" }) { ...DF }
    multiGetDynamicFields(keys: [
      { type: "u64", bcs: "@{cursor_0}" },
      { type: "u64", bcs: "@{cursor_1}" }
    ]) { ...DF }
  }
}

fragment DF on DynamicField {
  value { ... on MoveValue { json } }
}

{ # Accessing the elements of the ObjectBag via `object` and `address`.
  object(address: "@{obj_5_0}") {
    asMoveObject {
      df400: dynamicObjectField(name: { type: "u64", bcs: "@{cursor_0}" }) { ...DOF }
      df500: dynamicObjectField(name: { type: "u64", bcs: "@{cursor_1}" }) { ...DOF }
      multiGetDynamicObjectFields(keys: [
        { type: "u64", bcs: "@{cursor_0}" },
        { type: "u64", bcs: "@{cursor_1}" }
      ]) { ...DOF }
    }
  }

  address(address: "@{obj_5_0}", rootVersion: 8) {
    df400: dynamicObjectField(name: { type: "u64", bcs: "@{cursor_0}" }) { ...DOF }
    df500: dynamicObjectField(name: { type: "u64", bcs: "@{cursor_1}" }) { ...DOF }
    multiGetDynamicObjectFields(keys: [
      { type: "u64", bcs: "@{cursor_0}" },
      { type: "u64", bcs: "@{cursor_1}" }
    ]) { ...DOF }
  }
}

fragment DOF on DynamicField {
  value { ... on MoveObject { contents { json } } }
}

{ # Fetching an address at another checkpoint, and fetching its objects,
  # balances, and transactions. The owned objects and balances are scoped to
  # the address' checkpoint, while the transactions are scoped by the
  # checkpoint being viewed, which means it doesn't change between checkpoints.
  atCp0: address(address: "@{A}", atCheckpoint: 0) {
    balance(coinType: "sui::sui::SUI") {
      totalBalance
    }

    objects {
      nodes {
        address
        contents {
          type { repr }
          json
        }
      }
    }

    transactions {
      nodes {
        digest
      }
    }
  }

  atCp1: address(address: "@{A}", atCheckpoint: 1) {
    balance(coinType: "sui::sui::SUI") {
      totalBalance
    }

    objects {
      nodes {
        address
        contents {
          type { repr }
          json
        }
      }
    }

    transactions {
      nodes {
        digest
      }
    }
  }
}

