{
  failed: transactionEffects(digest: "@{digest_4}") { ...E }
  success: transactionEffects(digest: "@{digest_5}") { ...E }
}

fragment E on TransactionEffects {
  status

  transaction {
    sender { address }
  }

  gasEffects {
    gasObject {
      address
      version
      digest
    }
    gasSummary {
      computationCost
      storageCost
      storageRebate
      nonRefundableStorageFee
    }
  }

  balanceChanges {
    nodes {
      owner { address }
      coinType { repr }
      amount
    }
  }
}

